INSERT INTO policies (intent, title, body) VALUES
('baggage', 'Delayed, lost and damaged baggage',
 'Report delayed or damaged bags at the airport or online within 24 hours of arrival. Nimbus Air delivers delayed bags to the customer free of charge. A bag not found within 21 days is declared lost and compensated up to the published liability limit. Essential purchases are reimbursed up to 100 EUR per day for up to 5 days, with receipts.'),
('refund', 'Refunds',
 'Refundable fares are refunded to the original payment method within 7 business days. Non-refundable fares cannot be refunded, but airport taxes and fees are returned on request. If Nimbus Air cancels a flight, every customer may choose a full refund or free rebooking.'),
('booking_change', 'Changing a booking',
 'Changes are free within 24 hours of booking. After that, a change fee of 50 EUR applies plus any fare difference. Name corrections of up to 3 characters are free. Online changes close 2 hours before departure.'),
('flight_status', 'Flight status and delays',
 'Live flight status is available at nimbusair.example/status and in the Nimbus Air app. For arrival delays over 3 hours, customers may be entitled to compensation and can file a claim online with their booking reference.');
